import sys
import xml.etree.ElementTree as ET
import subprocess
import requests
import os

def main():
    if len(sys.argv) != 3:
        print("Usage: python run_jobs.py <config-path> <collector-url>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    collector_url = sys.argv[2]

    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
    except Exception as e:
        print(f"Error parsing XML file: {e}", file=sys.stderr)
        sys.exit(1)

    results = []
    for idx, command_elem in enumerate(root.findall('command'), 1):
        command = command_elem.text.strip()
        if not command:
            continue

        try:
            result = subprocess.run(
                command,
                shell=True,
                text=True,
                check=False,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                cwd=os.getcwd()
            )
            output = result.stdout + result.stderr
            output = ' '.join(output.splitlines())
            output = output.rstrip()

            print(f"{idx}: exit={result.returncode} output={output}")

            results.append({
                "command": command,
                "exit_status": result.returncode,
                "output": output
            })
        except Exception as e:
            print(f"Error executing command: {e}", file=sys.stderr)
            results.append({
                "command": command,
                "exit_status": 1,
                "output": ""
            })

    config_name = os.path.basename(os.path.normpath(config_path))
    payload = {
        "config": config_name,
        "results": results
    }

    try:
        response = requests.post(collector_url, json=payload, headers={"Content-Type": "application/json"})
        if 200 <= response.status_code < 300:
            sys.exit(0)
        else:
            print(f"Collector request failed with status {response.status_code}", file=sys.stderr)
            sys.exit(1)
    except Exception as e:
        print(f"Error sending results to collector: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
